//! Independent, transport-only review of the production byte decoder.
//! The golden corpus was generated by pinned CPython 3.14.6 json.loads(bytes).
//! Importing the private helper keeps this test off public production APIs.
#[path = "../src/consumers/json_wire.rs"]
mod json_wire;

use serde_json::Value;

fn corpus() -> Value {
    catabolic_core::decode_json(include_str!("fixtures/consumer_json_python314.json")).unwrap()
}

fn bytes(hex: &str) -> Vec<u8> {
    hex.as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect()
}

fn equivalent(actual: &Value, expected: &Value) -> bool {
    match (actual, expected) {
        (Value::Number(a), Value::Number(b)) => {
            let a = a.to_string();
            let b = b.to_string();
            if a.contains(['.', 'e', 'E']) || b.contains(['.', 'e', 'E']) {
                let a = a.parse::<f64>().unwrap();
                let b = b.parse::<f64>().unwrap();
                a.is_finite() && b.is_finite() && a.to_bits() == b.to_bits()
            } else {
                // JSON integer negative zero becomes integer zero in Python.
                a.trim_start_matches('-') == "0" && b == "0" || a == b
            }
        }
        (Value::Array(a), Value::Array(b)) => {
            a.len() == b.len() && a.iter().zip(b).all(|(a, b)| equivalent(a, b))
        }
        (Value::Object(a), Value::Object(b)) => {
            a.len() == b.len()
                && a.iter()
                    .all(|(key, value)| b.get(key).is_some_and(|b| equivalent(value, b)))
        }
        _ => actual == expected,
    }
}

#[test]
fn all_65793_byte_strings_of_length_zero_through_two_match_python() {
    let corpus = corpus();
    let successful = corpus["short_successes"].as_object().unwrap();
    assert_eq!(successful.len(), 213);
    let mut checked = 0;
    let mut check = |raw: &[u8]| {
        let hex = raw.iter().map(|b| format!("{b:02x}")).collect::<String>();
        match (json_wire::decode(raw), successful.get(&hex)) {
            (Ok(actual), Some(expected)) => assert!(equivalent(&actual, expected), "{hex}"),
            (Err(_), None) => (),
            (actual, expected) => panic!("{hex}: native {actual:?}; Python {expected:?}"),
        }
        checked += 1;
    };
    check(&[]);
    for first in 0..=255 {
        check(&[first]);
        for second in 0..=255 {
            check(&[first, second]);
        }
    }
    assert_eq!(checked, corpus["short_total"].as_u64().unwrap());
}

#[test]
fn unicode_boms_truncation_numbers_and_duplicate_keys_match_python() {
    let corpus = corpus();
    let cases = corpus["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 498);
    for case in cases {
        let actual = json_wire::decode(&bytes(case["hex"].as_str().unwrap()));
        if case.get("error").is_some() {
            assert!(actual.is_err(), "{}: {actual:?}", case["name"]);
        } else {
            let actual = actual.unwrap_or_else(|e| panic!("{}: {e}", case["name"]));
            assert!(
                equivalent(&actual, &case["expected"]),
                "{}: {actual:?} != {:?}",
                case["name"],
                case["expected"]
            );
        }
    }
}

#[test]
fn known_scalar_and_finite_number_restrictions_are_explicit() {
    for raw in [
        b"\"\xed\xa0\x80\"".as_slice(), // Python's UTF-8 surrogate-pass mode accepts this.
        b"\xff\xfe\"\0\0\xd8\"\0",      // Python accepts this unpaired UTF-16 surrogate too.
        b"\"\\ud800\"",
        b"NaN",
        b"Infinity",
        b"-Infinity",
        b"[1.7976931348623159e308]",
    ] {
        assert!(json_wire::decode(raw).is_err(), "{raw:?}");
    }
    // Keep the canonical byte codec strict while the remote helper accepts a BOM.
    let raw = b"\xef\xbb\xbf{}";
    assert!(catabolic_core::decode_json_bytes(raw).is_err());
    assert_eq!(json_wire::decode(raw).unwrap(), serde_json::json!({}));
}
